import{_ as t,c as a,o,ae as n}from"./chunks/framework.Cd-3tpCq.js";const g=JSON.parse('{"title":"Single CMS Page","description":"","frontmatter":{"outline":false,"examples":[{"id":"get-cms-page-by-id","title":"Get Single CMS Page","description":"Retrieve a single CMS page by its ID, including the resolved-locale translation and every stored translation.","query":"query getCmsPageDetail {\\n  page(id: \\"/api/shop/pages/1\\") {\\n    id\\n    _id\\n    layout\\n    createdAt\\n    updatedAt\\n    translation {\\n      id\\n      _id\\n      pageTitle\\n      urlKey\\n      htmlContent\\n      metaTitle\\n      metaDescription\\n      metaKeywords\\n      locale\\n      cmsPageId\\n    }\\n    translations(first: 10) {\\n      edges {\\n        node {\\n          _id\\n          locale\\n          pageTitle\\n          urlKey\\n        }\\n        cursor\\n      }\\n      pageInfo {\\n        hasNextPage\\n        hasPreviousPage\\n        startCursor\\n        endCursor\\n      }\\n      totalCount\\n    }\\n  }\\n}\\n","variables":"{}\\n","response":"{\\n  \\"data\\": {\\n    \\"page\\": {\\n      \\"id\\": \\"/api/shop/pages/1\\",\\n      \\"_id\\": 1,\\n      \\"layout\\": null,\\n      \\"createdAt\\": \\"2024-04-16T16:14:17+05:30\\",\\n      \\"updatedAt\\": \\"2024-04-16T16:14:17+05:30\\",\\n      \\"translation\\": {\\n        \\"id\\": \\"/api/shop/page_translations/1\\",\\n        \\"_id\\": 1,\\n        \\"pageTitle\\": \\"About Us\\",\\n        \\"urlKey\\": \\"about-us\\",\\n        \\"htmlContent\\": \\"<div class=\\\\\\"static-container\\\\\\">\\\\r\\\\n<div class=\\\\\\"mb-5\\\\\\">We are dedicated to providing high-quality products and services to our customers. Our team is passionate about innovation and customer satisfaction. We believe in transparency, integrity, and building long-term relationships with our users.</div>\\\\r\\\\n</div>\\",\\n        \\"metaTitle\\": \\"about us\\",\\n        \\"metaDescription\\": \\"\\",\\n        \\"metaKeywords\\": \\"aboutus\\",\\n        \\"locale\\": \\"en\\",\\n        \\"cmsPageId\\": \\"1\\"\\n      },\\n      \\"translations\\": {\\n        \\"edges\\": [\\n          {\\n            \\"node\\": {\\n              \\"_id\\": 42,\\n              \\"locale\\": \\"AR\\",\\n              \\"pageTitle\\": \\"\\\\u0645\\\\u0639\\\\u0644\\\\u0648\\\\u0645\\\\u0627\\\\u062a \\\\u0639\\\\u0646\\\\u0627\\",\\n              \\"urlKey\\": \\"about-us\\"\\n            },\\n            \\"cursor\\": \\"MA==\\"\\n          },\\n          {\\n            \\"node\\": {\\n              \\"_id\\": 1,\\n              \\"locale\\": \\"en\\",\\n              \\"pageTitle\\": \\"About Us\\",\\n              \\"urlKey\\": \\"about-us\\"\\n            },\\n            \\"cursor\\": \\"MQ==\\"\\n          }\\n        ],\\n        \\"pageInfo\\": {\\n          \\"hasNextPage\\": false,\\n          \\"hasPreviousPage\\": false,\\n          \\"startCursor\\": \\"MA==\\",\\n          \\"endCursor\\": \\"MQ==\\"\\n        },\\n        \\"totalCount\\": 2\\n      }\\n    }\\n  }\\n}\\n"},{"id":"get-cms-page-by-numeric-id","title":"Get Single CMS Page by Numeric ID","description":"The same query addressed with a plain numeric ID instead of the IRI form.","query":"query getCmsPageByNumericId {\\n  page(id: \\"1\\") {\\n    id\\n    _id\\n    layout\\n    createdAt\\n    updatedAt\\n    translation {\\n      id\\n      _id\\n      pageTitle\\n      urlKey\\n      htmlContent\\n      metaTitle\\n      metaDescription\\n      metaKeywords\\n      locale\\n      cmsPageId\\n    }\\n  }\\n}\\n","variables":"{}\\n","response":"{\\n  \\"data\\": {\\n    \\"page\\": {\\n      \\"id\\": \\"/api/shop/pages/1\\",\\n      \\"_id\\": 1,\\n      \\"layout\\": null,\\n      \\"createdAt\\": \\"2024-04-16T16:14:17+05:30\\",\\n      \\"updatedAt\\": \\"2024-04-16T16:14:17+05:30\\",\\n      \\"translation\\": {\\n        \\"id\\": \\"/api/shop/page_translations/1\\",\\n        \\"_id\\": 1,\\n        \\"pageTitle\\": \\"About Us\\",\\n        \\"urlKey\\": \\"about-us\\",\\n        \\"htmlContent\\": \\"<div class=\\\\\\"static-container\\\\\\">\\\\r\\\\n<div class=\\\\\\"mb-5\\\\\\">We are dedicated to providing high-quality products and services to our customers. Our team is passionate about innovation and customer satisfaction. We believe in transparency, integrity, and building long-term relationships with our users.</div>\\\\r\\\\n</div>\\",\\n        \\"metaTitle\\": \\"about us\\",\\n        \\"metaDescription\\": \\"\\",\\n        \\"metaKeywords\\": \\"aboutus\\",\\n        \\"locale\\": \\"en\\",\\n        \\"cmsPageId\\": \\"1\\"\\n      }\\n    }\\n  }\\n}\\n","commonErrors":[{"error":"Page not found","cause":"No CMS page exists for the supplied ID","solution":"List the available pages with the pages query first; the response carries `data.page` as `null` alongside an entry in `errors`"},{"error":"Invalid ID format","cause":"The ID is neither an IRI (`/api/shop/pages/1`) nor a numeric ID","solution":"Pass either form — `\\"/api/shop/pages/1\\"` or `\\"1\\"`"},{"error":"Missing storefront key","cause":"The request did not carry the storefront key header","solution":"Send `X-STOREFRONT-KEY` with every storefront GraphQL request"}]}]},"headers":[],"relativePath":"api/graphql-api/shop/queries/get-page.md","filePath":"api/graphql-api/shop/queries/get-page.md"}'),d={name:"api/graphql-api/shop/queries/get-page.md"};function r(i,e,s,l,c,h){return o(),a("div",null,e[0]||(e[0]=[n('<h1 id="single-cms-page" tabindex="-1">Single CMS Page <a class="header-anchor" href="#single-cms-page" aria-label="Permalink to &quot;Single CMS Page&quot;">​</a></h1><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>The <code>page(id:)</code> query retrieves a single CMS (Content Management System) page. Use this query to:</p><ul><li>Render a specific CMS page (e.g. About Us, Privacy Policy) in the storefront</li><li>Retrieve the full HTML content of a page for display</li><li>Access SEO metadata (meta title, description, keywords) for a specific page</li><li>Fetch locale-specific translation data for a page</li><li>Build dynamic page routes using <code>urlKey</code></li><li>Validate whether a page exists before rendering</li></ul><p>The query returns the page with <code>translation</code> — the single translation for the resolved locale — and <code>translations</code>, a cursor-paginated connection of every stored translation for that page. Use the <code>pages</code> query to list all available pages.</p><p>The <code>id</code> argument accepts both the IRI form (<code>/api/shop/pages/1</code>) and a plain numeric ID (<code>1</code>); both resolve to the same page.</p><h2 id="locale-handling" tabindex="-1">Locale Handling <a class="header-anchor" href="#locale-handling" aria-label="Permalink to &quot;Locale Handling&quot;">​</a></h2><p>The locale is resolved per request, in this order:</p><ol><li>The <code>X-Locale</code> header, when the supplied code is one of the locales enabled on the current channel.</li><li>The channel&#39;s default locale, when <code>X-Locale</code> is absent or names a locale the channel does not have enabled.</li></ol><p>The two translation fields then behave as follows:</p><ul><li><strong>Resolved locale</strong> — <code>translation</code> carries the record for the locale resolved above.</li><li><strong>Fallback</strong> — when the page has no translation for that locale, <code>translation</code> falls back to the application&#39;s fallback locale (<code>en</code> by default). If neither exists, <code>translation</code> is <code>null</code>.</li><li><strong>Reported locale</strong> — the <code>locale</code> field inside <code>translation</code> always states which locale the returned content actually came from.</li><li><strong>All languages</strong> — <code>translations</code> is unaffected by the request locale. It returns every stored translation, so a client can cache all languages of a page in one call.</li></ul><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID!</code></td><td>✅ Yes</td><td>Identifier of the page — IRI form (<code>/api/shop/pages/1</code>) or numeric (<code>1</code>).</td></tr></tbody></table><h2 id="possible-returns" tabindex="-1">Possible Returns <a class="header-anchor" href="#possible-returns" aria-label="Permalink to &quot;Possible Returns&quot;">​</a></h2><h3 id="page-fields" tabindex="-1">Page Fields <a class="header-anchor" href="#page-fields" aria-label="Permalink to &quot;Page Fields&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID!</code></td><td>IRI-style unique identifier (e.g. <code>/api/shop/pages/1</code>).</td></tr><tr><td><code>_id</code></td><td><code>Int!</code></td><td>Numeric database ID.</td></tr><tr><td><code>layout</code></td><td><code>String</code></td><td>Page layout template name. <code>null</code> when no layout is assigned.</td></tr><tr><td><code>createdAt</code></td><td><code>String</code></td><td>ISO 8601 timestamp of when the page was created.</td></tr><tr><td><code>updatedAt</code></td><td><code>String</code></td><td>ISO 8601 timestamp of when the page was last updated.</td></tr><tr><td><code>translation</code></td><td><code>PageTranslation</code></td><td>Translation for the resolved locale. <code>null</code> when the page has no translation at all.</td></tr><tr><td><code>translations</code></td><td><code>PageTranslationCursorConnection</code></td><td>Cursor connection over every stored translation for this page.</td></tr></tbody></table><h3 id="pagetranslation-fields" tabindex="-1">PageTranslation Fields <a class="header-anchor" href="#pagetranslation-fields" aria-label="Permalink to &quot;PageTranslation Fields&quot;">​</a></h3><p>Returned by <code>translation</code> and by each <code>translations</code> edge node.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID!</code></td><td>IRI-style ID of the translation record.</td></tr><tr><td><code>_id</code></td><td><code>Int!</code></td><td>Numeric translation record ID.</td></tr><tr><td><code>pageTitle</code></td><td><code>String!</code></td><td>Display title of the CMS page.</td></tr><tr><td><code>urlKey</code></td><td><code>String!</code></td><td>URL slug used to access the page (e.g. <code>about-us</code>).</td></tr><tr><td><code>htmlContent</code></td><td><code>String</code></td><td>Full HTML body content of the page.</td></tr><tr><td><code>metaTitle</code></td><td><code>String</code></td><td>SEO meta title tag.</td></tr><tr><td><code>metaDescription</code></td><td><code>String</code></td><td>SEO meta description tag.</td></tr><tr><td><code>metaKeywords</code></td><td><code>String</code></td><td>SEO meta keywords.</td></tr><tr><td><code>locale</code></td><td><code>String!</code></td><td>Locale code this translation belongs to (e.g. <code>en</code>, <code>fr</code>).</td></tr><tr><td><code>cmsPageId</code></td><td><code>String!</code></td><td>ID of the page this translation belongs to.</td></tr></tbody></table><h3 id="translations-connection-fields" tabindex="-1">Translations Connection Fields <a class="header-anchor" href="#translations-connection-fields" aria-label="Permalink to &quot;Translations Connection Fields&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>edges[].node</code></td><td><code>PageTranslation</code></td><td>A single translation record — fields as above.</td></tr><tr><td><code>edges[].cursor</code></td><td><code>String!</code></td><td>Cursor for this edge, used as <code>after</code> on the next request.</td></tr><tr><td><code>pageInfo.hasNextPage</code></td><td><code>Boolean!</code></td><td>Whether more translations follow the current slice.</td></tr><tr><td><code>pageInfo.hasPreviousPage</code></td><td><code>Boolean!</code></td><td>Whether translations precede the current slice.</td></tr><tr><td><code>pageInfo.startCursor</code></td><td><code>String</code></td><td>Cursor of the first edge in the slice.</td></tr><tr><td><code>pageInfo.endCursor</code></td><td><code>String</code></td><td>Cursor of the last edge in the slice.</td></tr><tr><td><code>totalCount</code></td><td><code>Int</code></td><td>Total translations stored for this page.</td></tr></tbody></table><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><h3 id="_1-render-a-cms-page" tabindex="-1">1. Render a CMS Page <a class="header-anchor" href="#_1-render-a-cms-page" aria-label="Permalink to &quot;1. Render a CMS Page&quot;">​</a></h3><p>Fetch a specific page by ID and render its <code>htmlContent</code> on a dedicated page route in the storefront.</p><h3 id="_2-seo-head-tags" tabindex="-1">2. SEO Head Tags <a class="header-anchor" href="#_2-seo-head-tags" aria-label="Permalink to &quot;2. SEO Head Tags&quot;">​</a></h3><p>Use <code>metaTitle</code>, <code>metaDescription</code>, and <code>metaKeywords</code> from the translation to populate <code>&lt;meta&gt;</code> tags dynamically.</p><h3 id="_3-page-validation" tabindex="-1">3. Page Validation <a class="header-anchor" href="#_3-page-validation" aria-label="Permalink to &quot;3. Page Validation&quot;">​</a></h3><p>Query a page before rendering to check whether it exists; handle a <code>null</code> page with a 404 page.</p><h3 id="_4-multi-language-content" tabindex="-1">4. Multi-language Content <a class="header-anchor" href="#_4-multi-language-content" aria-label="Permalink to &quot;4. Multi-language Content&quot;">​</a></h3><p>Send <code>X-Locale</code> to fetch a specific language, or read the whole <code>translations</code> connection to build a language switcher without one request per locale.</p><h3 id="_5-dynamic-page-routing" tabindex="-1">5. Dynamic Page Routing <a class="header-anchor" href="#_5-dynamic-page-routing" aria-label="Permalink to &quot;5. Dynamic Page Routing&quot;">​</a></h3><p>Use <code>urlKey</code> to implement client-side routing so users access pages via human-readable URLs (e.g. <code>/about-us</code>).</p><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Send the storefront key</strong> — every storefront GraphQL request needs the <code>X-STOREFRONT-KEY</code> header; without it the request is rejected before the query runs</li><li><strong>Pick one ID form and keep it</strong> — both the IRI (<code>/api/shop/pages/1</code>) and the numeric (<code>1</code>) form work; the IRI form matches what <code>id</code> returns, so round-tripping a response value needs no conversion</li><li><strong>Check <code>data.page</code> and <code>errors</code> together</strong> — an unknown or malformed ID returns <code>data.page</code> as <code>null</code> with an entry in <code>errors</code>; treat that as a 404 rather than an outage</li><li><strong>Read <code>translation.locale</code></strong> — it reports the locale the content actually came from, which differs from the requested one whenever the fallback applies</li><li><strong>Sanitize <code>htmlContent</code></strong> — the field is raw HTML authored in the admin panel; sanitize it before injecting into the DOM</li><li><strong>Cache per page and locale</strong> — cache keyed by page ID alone will serve the wrong language once a second locale is enabled</li><li><strong>Fetch only needed fields</strong> — omit <code>htmlContent</code> and <code>translations</code> when only the title and URL are needed; both grow the response several times over, and <code>htmlContent</code> carries a full HTML body</li><li><strong>Use <code>urlKey</code> for links</strong> — build storefront URLs from <code>urlKey</code> for SEO-friendly, human-readable routes</li></ol><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/graphql-api/shop/queries/get-pages.html">Get All CMS Pages</a> - Query all CMS pages</li><li><a href="/api/graphql-api/shop/queries/theme-customisations.html">Theme Customisations</a> - Query storefront theme customisations</li><li><a href="/api/graphql-api/pagination.html">Pagination Guide</a> - Cursor pagination documentation</li><li><a href="/api/graphql-api/shop-api.html">Shop API Overview</a> - Overview of Shop API resources</li></ul>',36)]))}const p=t(d,[["render",r]]);export{g as __pageData,p as default};
